export const PALETTES=[
 {name:'Apricot',paper:'#fff7e8',ink:'#463b36',muted:'#8e7363',sky:'#f2d8bd',sun:'#da805e',land:'#91a085',front:'#506f64'},
 {name:'Lilac',paper:'#faf4fc',ink:'#453955',muted:'#84728e',sky:'#ded4e8',sun:'#d69ac3',land:'#969ac0',front:'#5e6895'},
 {name:'Blue hour',paper:'#f4f4ed',ink:'#284255',muted:'#6b8995',sky:'#b4d4dc',sun:'#f2c17d',land:'#7a9db0',front:'#386573'}
];
export const SCENES=['Rolling hills','By the sea','Under the stars'];
export const EXAMPLE={version:1,kicker:'A LITTLE SOMETHING FOR YOU',title:'Good things take their time.',message:'Here is a little reminder that you are growing, even on the days when it is hard to see. Keep going. Your next chapter is already taking shape.',signature:'With love, CE',scene:0,palette:0,seed:412};
export function validateDraft(value){if(!value||value.version!==1)throw Error('Unsupported draft');const out={version:1};for(const[key,max]of[['kicker',32],['title',48],['message',220],['signature',40]]){if(typeof value[key]!=='string'||Array.from(value[key]).length>max)throw Error('Invalid '+key);out[key]=value[key];}for(const[key,max]of[['scene',SCENES.length],['palette',PALETTES.length]]){if(!Number.isInteger(value[key])||value[key]<0||value[key]>=max)throw Error('Invalid '+key);out[key]=value[key];}if(!Number.isInteger(value.seed)||value.seed<0||value.seed>0xffffffff)throw Error('Invalid seed');out.seed=value.seed;return out;}
export function randomFor(seed){return()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};}
export function wrapText(text,maxWidth,measure){const words=text.trim().split(/\s+/u).filter(Boolean),lines=[];let line='';for(const word of words){const candidate=line?line+' '+word:word;if(measure(candidate)<=maxWidth){line=candidate;continue;}if(line){lines.push(line);line='';}if(measure(word)<=maxWidth){line=word;continue;}const parts=typeof Intl.Segmenter==='function'?Array.from(new Intl.Segmenter(undefined,{granularity:'grapheme'}).segment(word),p=>p.segment):Array.from(word);for(const char of parts){if(line&&measure(line+char)>maxWidth){lines.push(line);line='';}line+=char;}}if(line)lines.push(line);return lines;}
export function fitText(text,maxWidth,maxLines,startSize,minSize,measureAtSize){for(let size=startSize;size>=minSize;size--){const lines=wrapText(text,maxWidth,t=>measureAtSize(t,size));if(lines.length<=maxLines)return{size,lines};}return{size:minSize,lines:wrapText(text,maxWidth,t=>measureAtSize(t,minSize))};}
